-- album-crm — importación de los equipos que ya estaban en seguimiento en el
-- Notion "Seguimiento Equipos". Mapeo de Estado -> etapa del funnel:
--   Sin contactar / Más adelante -> busqueda
--   En negociación / Visto bueno -> negociacion
--   Otro año                     -> perdido (motivo: "Otro año")
--   Cerrado                      -> ganado
--   Rechazado                    -> perdido (motivo: "Rechazado")
-- El campo "Responsable" del Notion (Lander/Pablo/Jaime) se guarda en
-- accounts.owner_name como texto informativo (todavía no hay cuentas de
-- usuario reales para Pablo/Jaime en la app).
--
-- Se desactiva el trigger de historial durante la carga y se rellena a mano
-- con la fecha real de creación en Notion, para no llenar "Actividad
-- reciente" de 45 entradas fechadas "ahora mismo".



alter table public.deals disable trigger deals_after_insert;


alter table public.deals enable trigger deals_after_insert;

